const entrada = $json || {};

function texto(valor) {
  return String(valor ?? '').trim();
}

function hashSimples(valor) {
  let hash = 0;

  for (let i = 0; i < valor.length; i++) {
    hash =
      ((hash << 5) - hash) +
      valor.charCodeAt(i);

    hash |= 0;
  }

  return Math.abs(hash)
    .toString(36)
    .toUpperCase()
    .padStart(7, '0');
}

function mapearFamilia(familia) {
  const mapa = {
    CABOS: 'Cabos e Condutores',
    CONECTORES: 'Conexões e Terminais',
    TERMINAIS: 'Conexões e Terminais',
    DISJUNTORES: 'Proteção Elétrica',
    CHAVES_SECCIONADORAS: 'Proteção Elétrica',
    POSTES: 'Estruturas e Ferragens',
    ISOLADORES: 'Estruturas e Ferragens',
    BARRAMENTOS: 'Equipamentos',
    TRANSFORMADORES: 'Equipamentos',
    ELETRODUTOS: 'Outros',
    CAIXAS_PASSAGEM: 'Outros',
    OUTROS: 'Outros'
  };

  return mapa[texto(familia).toUpperCase()] || 'Outros';
}

function mapearUnidade(unidade) {
  const valor = texto(unidade).toUpperCase();

  const mapa = {
    UN: 'UN',
    UND: 'UN',
    UNID: 'UN',
    UNIDADE: 'UN',
    PC: 'PC',
    PÇ: 'PC',
    PECA: 'PC',
    PEÇA: 'PC',
    M: 'M',
    METRO: 'M',
    METROS: 'M',
    KG: 'KG',
    CJ: 'CJ',
    CONJUNTO: 'CJ'
  };

  return mapa[valor] || null;
}

const codigoItem =
  texto(entrada.codigo_item);

const descricaoOriginal =
  texto(entrada.descricao_original);

const chaveNormalizada =
  texto(entrada.chave_normalizada_busca);

const familiaNormalizada =
  texto(entrada.familia_normalizada) ||
  texto(
    entrada.normalizacao_material
      ?.familia_sugerida
  ) ||
  'OUTROS';

if (!codigoItem) {
  throw new Error(
    'codigo_item não recebido no PREP - Candidato Material.'
  );
}

if (!descricaoOriginal) {
  throw new Error(
    `Descrição original ausente para ${codigoItem}.`
  );
}

if (!chaveNormalizada) {
  throw new Error(
    `Chave normalizada ausente para ${codigoItem}.`
  );
}

const codigoCandidato =
  `CAND-${hashSimples(chaveNormalizada)}`;

const fields = {
  Title:
    codigoCandidato,

  Material:
    descricaoOriginal,

  Familia:
    mapearFamilia(familiaNormalizada),

  Unidade_Padrao:
    mapearUnidade(
      entrada.unidade_original
    ),

  Marca_Ref: null,

  Observacao:
    texto(entrada.observacao_item) ||
    `Candidato gerado a partir do item ${codigoItem}`,

  Status:
    'Pendente Revisão',

  Subfamilia: null,

  Modelo_Ref: null,

  Especificacao_Tecnica:
    descricaoOriginal,

  Atributos_Essenciais: null,

  Sinonimos:
    descricaoOriginal,

  Revisao_Obrigatoria:
    true,

  Data_Atualizacao:
    new Date().toISOString().slice(0, 10),

  Nome_Normalizado:
    chaveNormalizada,

  Chave_Normalizada:
    chaveNormalizada,

  Categoria: null
};

return {
  json: {
    ...entrada,

    codigo_candidato:
      codigoCandidato,

    candidato_material: true,

    fields
  }
};

const entrada =
$('PREP - Candidato Material').first().json;

const registros =
Array.isArray($json.value)
? $json.value
: [];

const existe =
registros.length > 0;

const registro =
existe
? registros[0]
: null;

return {
  json: {
    ...entrada,

    candidato_existe: existe,

    material_sugerido:
      registro?.fields?.Title || null,

    material_oficial_id:
      registro
        ? Number(registro.id)
        : null,

    motivo_material:
      existe
        ? 'CANDIDATO_EXISTENTE'
        : 'CANDIDATO_NOVO'
  }
};

const entrada =
$('PREP - Candidato Material').first().json;

const criado =
$json;

return {
  json:{
    ...entrada,

    material_encontrado:true,

    material_sugerido:
      criado.fields.Title,

    material_oficial_id:
      Number(criado.id),

    motivo_material:
      'CANDIDATO_CRIADO'
  }
};

const itemOriginal =
  $('PREP - Buscar Material1').item.json || {};

const respostaGraph = $json || {};

const registros =
  Array.isArray(respostaGraph.value)
    ? respostaGraph.value
    : [];

const materialEncontrado =
  registros.length > 0
    ? registros[0]
    : null;

const fieldsMaterial =
  materialEncontrado?.fields || {};

const materialId =
  materialEncontrado?.id
    ? Number(materialEncontrado.id)
    : null;

const codigoMaterial =
  String(
    fieldsMaterial.Codigo_Neoenergia ||
    fieldsMaterial.CodMaterial ||
    ''
  ).trim();

const nomeMaterial =
  String(
    fieldsMaterial.Material ||
    fieldsMaterial.Title ||
    ''
  ).trim();

const encontrou =
  Boolean(materialEncontrado && materialId);

/*
 * IMPORTANTE:
 * Este workflow apenas SUGERE um Material Oficial.
 * Nunca aprova automaticamente o material do item.
 */
return {
  json: {
    ...itemOriginal,

    material_sugerido:
      encontrou
        ? (nomeMaterial || null)
        : null,

    material_oficial_id:
      encontrou
        ? materialId
        : null,

    codigo_neoenergia_sugerido:
      encontrou
        ? (codigoMaterial || null)
        : null,

    material_encontrado:
      encontrou,

    motivo_material:
      encontrou
        ? 'MATCH_EXATO_ATIVO'
        : 'SEM_MATCH_EXATO_ATIVO',

    estrategia_matching:
      'DESCRICAO_NORMALIZADA_EXATA',

    material_oficial:
      encontrou
        ? {
            id: materialId,

            codigo_neoenergia:
              codigoMaterial || null,

            material:
              nomeMaterial || null,

            nome_normalizado:
              fieldsMaterial.Nome_Normalizado || null,

            chave_normalizada:
              fieldsMaterial.Chave_Normalizada || null,

            familia:
              fieldsMaterial.Familia || null,

            subfamilia:
              fieldsMaterial.Subfamilia || null,

            categoria:
              fieldsMaterial.Categoria || null,

            unidade_padrao:
              fieldsMaterial.Unidade_Padrao || null,

            origem_catalogo:
              fieldsMaterial.Origem_Catalogo || null,

            status:
              fieldsMaterial.Status || null
          }
        : null
  }
};

/**
 * PREP - Buscar Material
 *
 * Objetivo:
 * - preservar integralmente o item recebido;
 * - identificar a família provável;
 * - normalizar abreviações, unidades e características técnicas;
 * - gerar uma chave estrita para busca no MaterialOficial;
 * - gerar uma chave-base para futura busca alternativa;
 * - não inventar características ausentes.
 */

const entrada = $json || {};

/* -------------------------------------------------------------------------- */
/* Helpers                                                                    */
/* -------------------------------------------------------------------------- */

function texto(valor) {
  return String(valor ?? '').trim();
}

function removerDecimaisZero(valor) {
  return valor.replace(
    /\b(\d+)\.0+\b/g,
    '$1'
  );
}

function removerAcentos(valor) {
  return texto(valor)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function escaparOData(valor) {
  return texto(valor).replace(/'/g, "''");
}

function aplicarMapaPorPalavra(valor, mapa) {
  let resultado = valor;

  const termos = Object.keys(mapa)
    .sort((a, b) => b.length - a.length);

  for (const termo of termos) {
    const substituto = mapa[termo];

    const termoEscapado = termo.replace(
      /[.*+?^${}()|[\]\\]/g,
      '\\$&'
    );

    resultado = resultado.replace(
      new RegExp(`\\b${termoEscapado}\\b`, 'g'),
      substituto
    );
  }

  return resultado;
}

function removerPalavras(valor, palavras) {
  let resultado = valor;

  for (const palavra of palavras) {
    resultado = resultado.replace(
      new RegExp(`\\b${palavra}\\b`, 'g'),
      ' '
    );
  }

  return resultado;
}

function limparEspacos(valor) {
  return texto(valor)
    .replace(/\s+/g, ' ')
    .trim();
}

/* -------------------------------------------------------------------------- */
/* Dicionários                                                                */
/* -------------------------------------------------------------------------- */

const sinonimosGlobais = {
  PÇ: 'UN',
  PC: 'UN',
  PCA: 'UN',
  PECA: 'UN',
  UND: 'UN',
  UNID: 'UN',
  UNIDADE: 'UN',

  METRO: 'M',
  METROS: 'M',

  QTD: 'QUANTIDADE',

  ELETR: 'ELETRICO',
  ELET: 'ELETRICO',

  TRIF: 'TRIFASICO',
  MONOF: 'MONOFASICO',

  EXT: 'EXTERNO',
  INT: 'INTERNO'
};

const sinonimosPorFamilia = {
  CABOS: {
    CU: 'COBRE',
    COB: 'COBRE',
    AL: 'ALUMINIO',
    ALUM: 'ALUMINIO',

    FLEX: 'FLEXIVEL',
    FLEXIV: 'FLEXIVEL',

    RIG: 'RIGIDO',

    COND: 'CONDUTOR',

    XLPE: 'XLPE',
    EPR: 'EPR',
    PVC: 'PVC'
  },

  DISJUNTORES: {
    DISJ: 'DISJUNTOR',
    DJ: 'DISJUNTOR',

    MONOP: 'MONOPOLAR',
    UNIP: 'MONOPOLAR',
    UNIPOLAR: 'MONOPOLAR',

    BIP: 'BIPOLAR',
    '2P': 'BIPOLAR',

    TRIP: 'TRIPOLAR',
    '3P': 'TRIPOLAR',

    TETRAP: 'TETRAPOLAR',
    '4P': 'TETRAPOLAR',

    CM: 'CAIXA MOLDADA',
    MCCB: 'CAIXA MOLDADA',
    MCB: 'MINIDISJUNTOR'
  },

  ELETRODUTOS: {
    ELETROD: 'ELETRODUTO',
    ELETRODUTO: 'ELETRODUTO',

    CORR: 'CORRUGADO',

    GALV: 'GALVANIZADO',

    PEAD: 'PEAD',
    PVC: 'PVC'
  },

  POSTES: {
    CONC: 'CONCRETO',

    DT: 'DUPLO T',
    DUPLOT: 'DUPLO T',

    CIRC: 'CIRCULAR'
  },

  TRANSFORMADORES: {
    TRAFO: 'TRANSFORMADOR',
    TRANSF: 'TRANSFORMADOR',

    OLEO: 'OLEO',
    SECO: 'SECO'
  },

  CONECTORES: {
    CONECT: 'CONECTOR',
    CONEC: 'CONECTOR',

    PERF: 'PERFURANTE',

    COMP: 'COMPRESSAO'
  },

  TERMINAIS: {
    TERM: 'TERMINAL',

    COMP: 'COMPRESSAO'
  },

  ISOLADORES: {
    ISOL: 'ISOLADOR',

    POLIM: 'POLIMERICO',

    PORC: 'PORCELANA'
  },

  BARRAMENTOS: {
    BARR: 'BARRAMENTO',

    CU: 'COBRE',
    AL: 'ALUMINIO'
  }
};

/*
 * Removemos apenas palavras de ligação.
 * Não remover “TIPO”, “CLASSE”, “CURVA”, “EXTERNO” ou “INTERNO”,
 * pois podem diferenciar materiais.
 */
const palavrasLigacao = [
  'DE',
  'DA',
  'DO',
  'DAS',
  'DOS',
  'EM',
  'PARA'
];

/* -------------------------------------------------------------------------- */
/* Identificação de família                                                   */
/* -------------------------------------------------------------------------- */

function identificarFamilia(valor) {
  const descricao = limparEspacos(valor);

  if (
    /\bCABO\b/.test(descricao) ||
    /\bCONDUTOR\b/.test(descricao)
  ) {
    return 'CABOS';
  }

  if (
    /\bDISJUNTOR\b/.test(descricao) ||
    /\bDISJ\b/.test(descricao) ||
    /\bMCCB\b/.test(descricao) ||
    /\bMCB\b/.test(descricao)
  ) {
    return 'DISJUNTORES';
  }

  if (
    /\bELETRODUTO\b/.test(descricao) ||
    /\bELETROD\b/.test(descricao)
  ) {
    return 'ELETRODUTOS';
  }

  if (/\bPOSTE\b/.test(descricao)) {
    return 'POSTES';
  }

  if (
    /\bTRANSFORMADOR\b/.test(descricao) ||
    /\bTRAFO\b/.test(descricao) ||
    /\bTRANSF\b/.test(descricao)
  ) {
    return 'TRANSFORMADORES';
  }

  if (/\bCONECTOR\b|\bCONECT\b|\bCONEC\b/.test(descricao)) {
    return 'CONECTORES';
  }

  if (/\bTERMINAL\b|\bTERM\b/.test(descricao)) {
    return 'TERMINAIS';
  }

  if (/\bISOLADOR\b|\bISOL\b/.test(descricao)) {
    return 'ISOLADORES';
  }

  if (/\bBARRAMENTO\b|\bBARR\b/.test(descricao)) {
    return 'BARRAMENTOS';
  }

  if (
    /\bCHAVE SECCIONADORA\b/.test(descricao) ||
    /\bSECCIONADORA\b/.test(descricao)
  ) {
    return 'CHAVES_SECCIONADORAS';
  }

  if (
    /\bCAIXA PASSAGEM\b/.test(descricao) ||
    /\bCAIXA DE PASSAGEM\b/.test(descricao)
  ) {
    return 'CAIXAS_PASSAGEM';
  }

  return 'OUTROS';
}

/* -------------------------------------------------------------------------- */
/* Padronização técnica                                                       */
/* -------------------------------------------------------------------------- */

function padronizarUnidades(valor) {
  let resultado = valor;

  // Seção de condutor
  resultado = resultado
    .replace(/(\d+(?:[.,]\d+)?)\s*MM\s*[²2]\b/g, '$1 MM2')
    .replace(/(\d+(?:[.,]\d+)?)\s*MM2\b/g, '$1 MM2')
    .replace(/(\d+(?:[.,]\d+)?)\s*MMQ\b/g, '$1 MM2');

  // Diâmetro e dimensões lineares
  resultado = resultado
    .replace(/(\d+(?:[.,]\d+)?)\s*MM\b/g, '$1 MM')
    .replace(/(\d+(?:[.,]\d+)?)\s*CM\b/g, '$1 CM')
    .replace(/(\d+(?:[.,]\d+)?)\s*M\b/g, '$1 M');

  // Corrente
  resultado = resultado
    .replace(/(\d+(?:[.,]\d+)?)\s*AMPERES?\b/g, '$1 A')
    .replace(/(\d+(?:[.,]\d+)?)\s*AMP\b/g, '$1 A')
    .replace(/(\d+(?:[.,]\d+)?)\s*A\b/g, '$1 A');

  // Tensão
  resultado = resultado
    .replace(/(\d+(?:[.,]\d+)?)\s*KV\b/g, '$1 KV')
    .replace(/(\d+(?:[.,]\d+)?)\s*V\b/g, '$1 V');

  // Potência
  resultado = resultado
    .replace(/(\d+(?:[.,]\d+)?)\s*KVA\b/g, '$1 KVA')
    .replace(/(\d+(?:[.,]\d+)?)\s*MVA\b/g, '$1 MVA')
    .replace(/(\d+(?:[.,]\d+)?)\s*KW\b/g, '$1 KW')
    .replace(/(\d+(?:[.,]\d+)?)\s*MW\b/g, '$1 MW');

// Força / carga mecânica
resultado = resultado
  .replace(/(\d+(?:[.,]\d+)?)\s*DAN\b/g, '$1 DAN');

  // Capacidade de interrupção
  resultado = resultado
    .replace(/(\d+(?:[.,]\d+)?)\s*KA\b/g, '$1 KA');

  // Potência mecânica
  resultado = resultado
    .replace(/(\d+(?:[.,]\d+)?)\s*CV\b/g, '$1 CV')
    .replace(/(\d+(?:[.,]\d+)?)\s*HP\b/g, '$1 HP');

  return resultado;
}

function padronizarNumeros(valor) {
  return valor.replace(
    /(\d),(\d)/g,
    '$1.$2'
  );
}

function padronizarTensoesDeCabo(valor, familia) {
  if (familia !== 'CABOS') {
    return valor;
  }

  let resultado = valor;

  /*
   * Normaliza somente equivalências explicitamente
   * informadas na descrição.
   * Não completa classes de tensão ausentes.
   */
  resultado = resultado
    .replace(
      /\b0[.,]6\s*[\/\\-]\s*1\s*KV\b/g,
      '0.6/1 KV'
    )
    .replace(
      /\b0\s+6\s+1\s+KV\b/g,
      '0.6/1 KV'
    )
    .replace(
      /\b600\s*[\/\\-]\s*1000\s*V\b/g,
      '0.6/1 KV'
    )
    .replace(
      /\b450\s*[\/\\-]\s*750\s*V\b/g,
      '450/750 V'
    );

  return resultado;
}

function padronizarPolos(valor, familia) {
  if (familia !== 'DISJUNTORES') {
    return valor;
  }

  return valor
    .replace(/\b1\s*P\b/g, 'MONOPOLAR')
    .replace(/\b2\s*P\b/g, 'BIPOLAR')
    .replace(/\b3\s*P\b/g, 'TRIPOLAR')
    .replace(/\b4\s*P\b/g, 'TETRAPOLAR');
}

function padronizarDimensoes(valor) {
  return valor
    .replace(
      /(\d+(?:\.\d+)?)\s*[X×]\s*(\d+(?:\.\d+)?)\s*MM\b/g,
      '$1 X $2 MM'
    )
    .replace(
      /(\d+(?:\.\d+)?)\s*[X×]\s*(\d+(?:\.\d+)?)\s*[X×]\s*(\d+(?:\.\d+)?)\s*MM\b/g,
      '$1 X $2 X $3 MM'
    );
}

/* -------------------------------------------------------------------------- */
/* Geração das chaves                                                         */
/* -------------------------------------------------------------------------- */

function normalizarDescricao(valor) {
  let resultado = removerAcentos(valor)
    .toUpperCase()
    .replace(/²/g, '2')
    .replace(/[“”"'`´]/g, ' ')
    .replace(/[(){}\[\]]/g, ' ')
    .replace(/[;:]/g, ' ')
    .replace(/–|—/g, '-');

  resultado = limparEspacos(resultado);

  const familia = identificarFamilia(resultado);

  resultado = aplicarMapaPorPalavra(
    resultado,
    sinonimosGlobais
  );

  const regrasFamilia =
    sinonimosPorFamilia[familia] || {};

  resultado = aplicarMapaPorPalavra(
    resultado,
    regrasFamilia
  );

  resultado = padronizarNumeros(resultado);
  resultado = removerDecimaisZero(resultado);
  resultado = padronizarUnidades(resultado);
  resultado = padronizarTensoesDeCabo(
    resultado,
    familia
  );
  resultado = padronizarPolos(
    resultado,
    familia
  );
  resultado = padronizarDimensoes(resultado);

  /*
   * Preserva "/" em tensões como 0.6/1 KV e códigos como 12/600.
   * Preserva "." para valores decimais.
   */
  resultado = resultado
    .replace(/[^A-Z0-9./]+/g, ' ');

  resultado = removerPalavras(
    resultado,
    palavrasLigacao
  );

  resultado = limparEspacos(resultado);

  return {
    descricao_normalizada: resultado,
    familia
  };
}

function gerarChaveBase(chaveEstrita, familia) {
  let resultado = chaveEstrita;

  /*
   * A chave-base remove poucos atributos opcionais.
   * Ela não deve ser usada para aprovação automática.
   * Serve apenas para uma futura busca de candidatos.
   */
  if (familia === 'CABOS') {
    resultado = resultado
      .replace(/\b0\.6\/1 KV\b/g, ' ')
      .replace(/\b450\/750 V\b/g, ' ');
  }

  resultado = resultado
    .replace(/\bPRETO\b/g, ' ')
    .replace(/\bAZUL\b/g, ' ')
    .replace(/\bVERMELHO\b/g, ' ')
    .replace(/\bVERDE\b/g, ' ')
    .replace(/\bAMARELO\b/g, ' ')
    .replace(/\bBRANCO\b/g, ' ');

  return limparEspacos(resultado);
}

/* -------------------------------------------------------------------------- */
/* Validação de entrada                                                       */
/* -------------------------------------------------------------------------- */

const codigoItem = texto(entrada.codigo_item);

const descricaoOriginal =
  texto(entrada.descricao_original);

if (!codigoItem) {
  throw new Error(
    'codigo_item não recebido no workflow de normalização.'
  );
}

if (!descricaoOriginal) {
  return {
    json: {
      ...entrada,

      chave_normalizada_busca: null,
      chave_normalizada_base: null,
      familia_normalizada: null,

      material_sugerido: null,
      material_oficial_id: null,
      material_encontrado: false,
      motivo_material: 'DESCRICAO_AUSENTE'
    }
  };
}

/* -------------------------------------------------------------------------- */
/* Processamento                                                               */
/* -------------------------------------------------------------------------- */

const normalizacao =
  normalizarDescricao(descricaoOriginal);

const chaveEstrita =
  normalizacao.descricao_normalizada;

const chaveBase =
  gerarChaveBase(
    chaveEstrita,
    normalizacao.familia
  );

return {
  json: {
    ...entrada,

    normalizacao_material: {
      ...(entrada.normalizacao_material || {}),

      descricao_original:
        descricaoOriginal,

      descricao_normalizada:
        chaveEstrita,

      familia_sugerida:
        normalizacao.familia,

      chave_base:
        chaveBase
    },

    familia_normalizada:
      normalizacao.familia,

    chave_normalizada_busca:
      chaveEstrita,

    chave_normalizada_base:
      chaveBase,

    chave_normalizada_odata:
      escaparOData(chaveEstrita)
  }
};

const entrada = $json || {};

const descricao =
  String(
    entrada.chave_normalizada_busca ||
    entrada.normalizacao_material?.descricao_normalizada ||
    ''
  ).trim();

const familia =
  entrada.familia_normalizada ||
  entrada.normalizacao_material?.familia_sugerida ||
  'OUTROS';

function extrairAtributosTecnicos(texto) {
  const encontrados = [];

  const regex =
    /\b(\d+(?:\.\d+)?)\s*(KV|V|MM2|MM|CM|M|A|KA|KVA|MVA|KW|MW|CV|HP|DAN|KN)\b/g;

  let match;

  while ((match = regex.exec(texto)) !== null) {
    encontrados.push({
      valor: Number(match[1]),
      unidade: match[2],
      token: `${match[1]} ${match[2]}`
    });
  }

  return encontrados;
}

function extrairTokensTextuais(texto) {
  const unidades = new Set([
    'KV', 'V', 'MM2', 'MM', 'CM', 'M',
    'A', 'KA', 'KVA', 'MVA', 'KW',
    'MW', 'CV', 'HP', 'DAN', 'KN'
  ]);

  return [...new Set(
    texto
      .split(/\s+/)
      .map(t => t.trim())
      .filter(Boolean)
      .filter(t => !/^\d+(?:\.\d+)?$/.test(t))
      .filter(t => !unidades.has(t))
  )];
}

const atributosTecnicos =
  extrairAtributosTecnicos(descricao);

const tokensTextuais =
  extrairTokensTextuais(descricao);

return {
  json: {
    ...entrada,

    busca_candidatos: {
      familia,
      descricao_normalizada: descricao,
      atributos_tecnicos: atributosTecnicos,
      tokens_textuais: tokensTextuais,
      estrategia: 'BUSCA_CANDIDATOS'
    }
  }
};

const entrada =
  $('CODE - Preparar Candidatos').item.json || {};

const respostaGraph = $json || {};

const candidatos =
  Array.isArray(respostaGraph.value)
    ? respostaGraph.value
    : [];

const busca =
  entrada.busca_candidatos || {};

const atributosEntrada =
  Array.isArray(busca.atributos_tecnicos)
    ? busca.atributos_tecnicos
    : [];

const tokensEntrada =
  Array.isArray(busca.tokens_textuais)
    ? busca.tokens_textuais
    : [];

/* -------------------------------------------------------------------------- */
/* Helpers                                                                    */
/* -------------------------------------------------------------------------- */

function texto(valor) {
  return String(valor ?? '').trim();
}

function removerAcentos(valor) {
  return texto(valor)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function limparEspacos(valor) {
  return texto(valor)
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizarTexto(valor) {
  let resultado =
    removerAcentos(valor)
      .toUpperCase()
      .replace(/²/g, '2')
      .replace(/(\d),(\d)/g, '$1.$2');

  /*
   * Abreviações importantes para o catálogo atual.
   */
  resultado = resultado
    .replace(/\bPOLIM\b/g, 'POLIMERICO')
    .replace(/\bPORC\b/g, 'PORCELANA')
    .replace(/\bPORCE\b/g, 'PORCELANA')
    .replace(/\bISOL\b/g, 'ISOLADOR');

  /*
   * Separa números das principais unidades técnicas.
   */
  resultado = resultado
    .replace(
      /(\d+(?:\.\d+)?)\s*(KV|V|MM2|MM|CM|M|KA|KVA|MVA|KW|MW|CV|HP|DAN|KN|A)\b/g,
      '$1 $2'
    );

  /*
   * 15.0 → 15
   */
  resultado = resultado.replace(
    /\b(\d+)\.0+\b/g,
    '$1'
  );

  resultado = resultado
    .replace(/[^A-Z0-9./]+/g, ' ');

  return limparEspacos(resultado);
}

function extrairAtributosTecnicos(valor) {
  const resultado = [];

  const descricao =
    normalizarTexto(valor);

  const regex =
    /\b(\d+(?:\.\d+)?)\s*(KV|V|MM2|MM|CM|M|KA|KVA|MVA|KW|MW|CV|HP|DAN|KN|A)\b/g;

  let match;

  while ((match = regex.exec(descricao)) !== null) {
    resultado.push({
      valor: Number(match[1]),
      unidade: match[2],
      token: `${Number(match[1])} ${match[2]}`
    });
  }

  return resultado;
}

function extrairTokensTextuais(valor) {
  const descricao =
    normalizarTexto(valor);

  const unidades = new Set([
    'KV',
    'V',
    'MM2',
    'MM',
    'CM',
    'M',
    'A',
    'KA',
    'KVA',
    'MVA',
    'KW',
    'MW',
    'CV',
    'HP',
    'DAN',
    'KN'
  ]);

  return [
    ...new Set(
      descricao
        .split(/\s+/)
        .filter(Boolean)
        .filter(
          token =>
            !/^\d+(?:\.\d+)?$/.test(token)
        )
        .filter(
          token =>
            !unidades.has(token)
        )
    )
  ];
}

function mesmoNumero(a, b) {
  return Math.abs(Number(a) - Number(b)) < 0.000001;
}

/* -------------------------------------------------------------------------- */
/* Avaliação                                                                  */
/* -------------------------------------------------------------------------- */

const avaliados = candidatos.map(candidato => {
  const fields =
    candidato?.fields || {};

  const descricao =
    fields.Nome_Normalizado ||
    fields.Material ||
    fields.Title ||
    '';

  const descricaoNormalizada =
    normalizarTexto(descricao);

  const atributosCandidato =
    extrairAtributosTecnicos(descricao);

  const tokensCandidato =
    extrairTokensTextuais(descricao);

  /*
   * Tokens da entrada que NÃO aparecem neste candidato
   * específico. Calculado por candidato, pois cada um
   * pode cobrir um subconjunto diferente dos tokens.
   */
  const tokensExtrasEntrada =
    tokensEntrada.filter(token =>
      !tokensCandidato.includes(token)
    );

  /*
   * REGRA DE SEGURANÇA:
   *
   * Todos os atributos técnicos existentes na entrada
   * precisam existir também no candidato com o MESMO
   * valor e unidade.
   *
   * Exemplo:
   *
   * entrada = 15 KV
   * candidato = 36.2 KV
   *
   * → candidato eliminado.
   */
  const atributosCompativeis =
    atributosEntrada.every(atributoEntrada =>
      atributosCandidato.some(atributoCandidato =>
        atributoEntrada.unidade === atributoCandidato.unidade &&
        mesmoNumero(
          atributoEntrada.valor,
          atributoCandidato.valor
        )
      )
    );

  /*
   * Percentual dos termos textuais encontrados.
   *
   * Ordem das palavras não importa.
   */
  const tokensEncontrados =
    tokensEntrada.filter(token =>
      tokensCandidato.includes(token)
    );

  const scoreTextual =
    tokensEntrada.length > 0
      ? tokensEncontrados.length / tokensEntrada.length
      : 0;

  /*
   * Para esta segunda camada:
   *
   * - atributos técnicos precisam ser 100% compatíveis;
   * - pelo menos 60% dos tokens textuais precisam coincidir.
   */
  const elegivel =
    atributosCompativeis &&
    scoreTextual >= 0.60;

  return {
    id:
      candidato?.id
        ? Number(candidato.id)
        : null,

    codigo_neoenergia:
      fields.Codigo_Neoenergia || null,

    material:
      fields.Material ||
      fields.Title ||
      null,

    nome_normalizado:
      fields.Nome_Normalizado || null,

    tokens_extras_entrada:
      tokensExtrasEntrada,

    categoria:
      fields.Categoria || null,

    status:
      fields.Status || null,

    descricao_avaliada:
      descricaoNormalizada,

    atributos_tecnicos:
      atributosCandidato,

    tokens_textuais:
      tokensCandidato,

    atributos_compativeis:
      atributosCompativeis,

    tokens_encontrados:
      tokensEncontrados,

    score_textual:
      Number(scoreTextual.toFixed(4)),

    elegivel
  };
});

/* -------------------------------------------------------------------------- */
/* Ranking                                                                    */
/* -------------------------------------------------------------------------- */

const elegiveis =
  avaliados
    .filter(c => c.elegivel)
    .sort((a, b) => {
      if (b.score_textual !== a.score_textual) {
        return b.score_textual - a.score_textual;
      }

      return (a.id || 0) - (b.id || 0);
    });

const melhor =
  elegiveis.length > 0
    ? elegiveis[0]
    : null;

const segundo =
  elegiveis.length > 1
    ? elegiveis[1]
    : null;

/*
 * Só consideramos candidato único quando:
 *
 * - existe um candidato elegível;
 * - e não existe empate no score com outro candidato.
 *
 * Mesmo assim continua sendo SUGESTÃO.
 * Não há aprovação automática.
 */
const candidatoUnico =
  Boolean(
    melhor &&
    (
      !segundo ||
      melhor.score_textual >
        segundo.score_textual
    )
  );

/* -------------------------------------------------------------------------- */
/* Saída                                                                      */
/* -------------------------------------------------------------------------- */

return {
  json: {
    ...entrada,

    material_sugerido:
      candidatoUnico
        ? melhor.material
        : null,

    material_oficial_id:
      candidatoUnico
        ? melhor.id
        : null,

    codigo_neoenergia_sugerido:
      candidatoUnico
        ? melhor.codigo_neoenergia
        : null,

    /*
     * Encontramos uma sugestão forte,
     * mas NÃO estamos aprovando o material.
     */
    material_encontrado:
      candidatoUnico,

    match_automatico:
      false,

    revisao_humana_obrigatoria:
      true,

    motivo_material:
      candidatoUnico
        ? 'CANDIDATO_TECNICO_UNICO'
        : elegiveis.length > 1
          ? 'CANDIDATOS_AMBIGUOS'
          : 'SEM_CANDIDATO_COMPATIVEL',

    estrategia_matching:
      'CANDIDATOS_ATRIBUTOS_TECNICOS',

    avaliacao_candidatos: {
      quantidade_recebida:
        candidatos.length,

      quantidade_elegivel:
        elegiveis.length,

      melhor_candidato:
        melhor,

      candidatos_elegiveis:
        elegiveis.slice(0, 5)
    }
  }
};
